CREATE DATABASE IF NOT EXISTS sokoni CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sokoni;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS admin_logs,price_history,notifications,reports,messages,favorites,listing_images,listings,villages,wards,districts,crops,crop_categories,units,listing_statuses,listing_types,users,user_roles,regions;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE user_roles(id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(30) NOT NULL UNIQUE,description VARCHAR(255),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE regions(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE districts(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,region_id INT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,UNIQUE KEY uq_district(region_id,name),FOREIGN KEY(region_id) REFERENCES regions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE wards(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,district_id INT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,UNIQUE KEY uq_ward(district_id,name),FOREIGN KEY(district_id) REFERENCES districts(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE villages(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ward_id INT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,UNIQUE KEY uq_village(ward_id,name),FOREIGN KEY(ward_id) REFERENCES wards(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE crop_categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,description VARCHAR(255)) ENGINE=InnoDB;
CREATE TABLE crops(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id INT UNSIGNED NULL,name VARCHAR(120) NOT NULL UNIQUE,description VARCHAR(255),FOREIGN KEY(category_id) REFERENCES crop_categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE units(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(60) NOT NULL UNIQUE,abbreviation VARCHAR(20),description VARCHAR(255)) ENGINE=InnoDB;
CREATE TABLE listing_types(id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(30) NOT NULL UNIQUE,description VARCHAR(255)) ENGINE=InnoDB;
CREATE TABLE listing_statuses(id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(30) NOT NULL UNIQUE,description VARCHAR(255)) ENGINE=InnoDB;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,role_id TINYINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,phone VARCHAR(30) NOT NULL UNIQUE,email VARCHAR(190) UNIQUE,password_hash VARCHAR(255) NOT NULL,region_id INT UNSIGNED NULL,district_id INT UNSIGNED NULL,village VARCHAR(120),profile_image VARCHAR(255),phone_verified TINYINT(1) NOT NULL DEFAULT 0,email_verified TINYINT(1) NOT NULL DEFAULT 0,account_status ENUM('active','pending','suspended','blocked') NOT NULL DEFAULT 'active',last_login DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES user_roles(id),FOREIGN KEY(region_id) REFERENCES regions(id) ON DELETE SET NULL,FOREIGN KEY(district_id) REFERENCES districts(id) ON DELETE SET NULL,INDEX(account_status),INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE listings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,listing_type_id TINYINT UNSIGNED NOT NULL,crop_id INT UNSIGNED NOT NULL,unit_id INT UNSIGNED NOT NULL,region_id INT UNSIGNED NOT NULL,district_id INT UNSIGNED NULL,ward_id INT UNSIGNED NULL,village_id INT UNSIGNED NULL,quantity DECIMAL(15,3) NOT NULL,price DECIMAL(15,2) NOT NULL,note TEXT,status_id TINYINT UNSIGNED NOT NULL,featured TINYINT(1) NOT NULL DEFAULT 0,views INT UNSIGNED NOT NULL DEFAULT 0,expires_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(listing_type_id) REFERENCES listing_types(id),FOREIGN KEY(crop_id) REFERENCES crops(id),FOREIGN KEY(unit_id) REFERENCES units(id),FOREIGN KEY(region_id) REFERENCES regions(id),FOREIGN KEY(district_id) REFERENCES districts(id) ON DELETE SET NULL,FOREIGN KEY(ward_id) REFERENCES wards(id) ON DELETE SET NULL,FOREIGN KEY(village_id) REFERENCES villages(id) ON DELETE SET NULL,FOREIGN KEY(status_id) REFERENCES listing_statuses(id),INDEX(status_id),INDEX(created_at),INDEX(region_id),INDEX(crop_id),INDEX(featured)) ENGINE=InnoDB;
CREATE TABLE listing_images(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT UNSIGNED NOT NULL,path VARCHAR(255) NOT NULL,sort_order INT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(listing_id) REFERENCES listings(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE favorites(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,listing_id BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_favorite(user_id,listing_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(listing_id) REFERENCES listings(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sender_id BIGINT UNSIGNED NOT NULL,receiver_id BIGINT UNSIGNED NOT NULL,listing_id BIGINT UNSIGNED NULL,body TEXT NOT NULL,read_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(receiver_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(listing_id) REFERENCES listings(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE reports(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reporter_id BIGINT UNSIGNED NOT NULL,listing_id BIGINT UNSIGNED NULL,reason VARCHAR(120) NOT NULL,details TEXT,status ENUM('open','reviewed','resolved','rejected') NOT NULL DEFAULT 'open',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(reporter_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(listing_id) REFERENCES listings(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(190) NOT NULL,body TEXT,read_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE price_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT UNSIGNED NOT NULL,price DECIMAL(15,2) NOT NULL,recorded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(listing_id) REFERENCES listings(id) ON DELETE CASCADE,INDEX(listing_id,recorded_at)) ENGINE=InnoDB;
CREATE TABLE admin_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT UNSIGNED NOT NULL,action VARCHAR(120) NOT NULL,target_table VARCHAR(80),target_id BIGINT UNSIGNED,details TEXT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
